        rendered = _PATH_AS_POSIX(relative)
    except (OSError, RuntimeError, ValueError):
        return None
    if rendered == ".":
        return "."
    if (
        not rendered
        or rendered.startswith("/")
        or "\\" in rendered
        or any(part in {"", ".", ".."} for part in rendered.split("/"))
    ):
